-- KORAK 2: Testni podaci za tri sezone; svi podaci su izmisljeni.
-- Sezone: 2023/2024, 2024/2025 i 2025/2026 (rujan - lipanj).
-- Pokrenuti JEDNOM nakon azurirane skripte 01, nad PRAZNIM tablicama.
-- Ovo zamjenjuje staru skriptu 02, nije nadogradnja vec upisanih podataka.
-- Postojeci podaci se ne brisu. Duplikati prekidaju transakciju.
-- Zadrzana su imena 24 clana, 3 trenera, 2 bazena i 3 tipa clanarine.
-- Isti clanovi imaju zaseban upis za svaku sezonu, bez preklapanja.
-- Svaka sezona: 6 grupa (po dvije na svakoj razini), po 4 clana u grupi.
-- Treneri rotiraju izmedju grupa po sezonama; povijesne grupe se ne prepisuju.
-- Dva termina tjedno; zimska stanka 24.12.-6.1.; postoje i otkazani treninzi.
-- Svaki odrzani trening ima evidenciju za svakog clana pripadajuce grupe.
-- Dvije discipline: 50 m slobodno i 50 m ledno; sva mjerenja u bazenu od 25 m.
-- Mjerenja: 5.9., 20.1. i 25.6. za svakog clana i disciplinu, svake sezone.
-- Za usporedbu koristiti dob na pocetnom mjerenju i dolaznost od 5.9. do 25.6.
-- Napredak (%) = (pocetno - zavrsno vrijeme) / pocetno vrijeme * 100.
-- Podaci ukljucuju poboljsanja, slabije rezultate, izostanke i opravdane izostanke.
-- Odnosi u rezultatima su NAMJERNO SINTETICKI, nisu dokaz uzrocnosti.
-- Clanarine: svi mjeseci aktivnih sezona, pune/djelomicne/zakasnjele uplate i dug.
-- ID-ove disciplina i rezultata generira baza; u praznoj tablici discipline su 1 i 2.

